"""Parallel normal uploads, followed only by USB model verification and conditional repair."""
import argparse
from concurrent.futures import ThreadPoolExecutor, as_completed
from datetime import datetime
import importlib.util
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile

USB_VENDOR_IDS = {0x303A, 0x10C4, 0x1A86, 0x0403}


def select_ports(available, requested=None):
    """Select explicit USB adapters or common ESP adapters, excluding motherboard UARTs."""
    adapters = {port.device.casefold(): port for port in available if port.vid is not None}
    if requested:
        names = [name.strip() for name in requested.split(',')]
        if any(not name or name.casefold() not in adapters for name in names):
            raise ValueError('Every requested port must be a connected USB serial adapter')
        return list(dict.fromkeys(adapters[name.casefold()].device for name in names))
    return sorted({port.device for port in available if port.vid in USB_VENDOR_IDS})


def load_plan(path):
    """Validate the generated normal-upload plan and model package before opening a port."""
    plan = json.loads(path.read_text(encoding='utf-8'))
    arguments = plan['arguments']
    if not isinstance(arguments, list) or not all(isinstance(value, str) for value in arguments):
        raise ValueError('Invalid upload arguments')
    if arguments.count('write-flash') != 1 or arguments.count('@PORT@') != 1:
        raise ValueError('Expected the normal serial firmware upload command')
    if not Path(plan['uploader']).is_file() or not Path(plan['firmware']).is_file():
        raise ValueError('Normal uploader/firmware is missing; rebuild first')
    if arguments[-1] != plan['firmware']:
        raise ValueError('Upload plan does not end with the normal application image')
    fs = plan['filesystem']
    if (type(fs['offset']) is not int or type(fs['size']) is not int or fs['offset'] < 0x10000
            or fs['size'] <= 0 or fs['offset'] % 4096 or fs['size'] % 4096
            or fs['offset'] + fs['size'] > 8 * 1024 * 1024):
        raise ValueError('Invalid model partition bounds')
    clean_image = Path(fs['image']).read_bytes()
    if len(clean_image) != fs['size']:
        raise ValueError('Model verification image has the wrong size')
    spec = importlib.util.spec_from_file_location('model_filesystem', plan['helper'])
    helper = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(helper)
    files = helper.read_package(plan['modelPackage'])
    helper.verify_filesystem(clean_image, files, fs['config'])
    return plan, (helper, files, clean_image)


def log_tail(path):
    try:
        lines = path.read_text(encoding='utf-8', errors='replace').splitlines()
        return ' | '.join(line.strip() for line in lines[-8:] if line.strip())[-1600:]
    except OSError:
        return ''


def read_partition(port, connection, fs, temporary, execute):
    """Read checksum-validated 64 KiB blocks; keep the CPU in the loader until the snapshot is complete."""
    block_size = 64 * 1024
    result = bytearray()
    command_prefix = list(connection)
    command_prefix[command_prefix.index('--after') + 1] = 'no-reset'
    destination = Path(temporary) / 'models-read-block.bin'
    for offset in range(0, fs['size'], block_size):
        size = min(block_size, fs['size'] - offset)
        for attempt in range(3):
            prefix = list(command_prefix)
            if attempt:
                prefix[prefix.index('--baud') + 1] = '115200'
            command = prefix + ['read-flash', hex(fs['offset'] + offset), hex(size), str(destination)]
            if execute(command):
                data = destination.read_bytes()
                if len(data) == size:
                    result.extend(data)
                    break
            if attempt == 2:
                raise RuntimeError(f'Could not verify model read block at {hex(fs["offset"] + offset)}; no repair attempted')
            print(f'[{port}] Retrying model read block at {hex(fs["offset"] + offset)}...', flush=True)
        if offset % (8 * block_size) == 0 or len(result) == fs['size']:
            print(f'[{port}] Model readback: {len(result) * 100 // fs["size"]}%', flush=True)
    return bytes(result)


def upload_port(port, plan, assets, logs):
    """Use exact normal-upload arguments; inspect model contents and repair only on mismatch."""
    log_path = logs / ('port-' + re.sub(r'[^A-Za-z0-9_.-]', '_', port) + '.log')
    helper, files, clean_image = assets
    fs = plan['filesystem']
    arguments = [port if argument == '@PORT@' else argument for argument in plan['arguments']]
    upload = [plan['uploader'], *arguments]
    connection = [plan['uploader'], *arguments[:arguments.index('write-flash')]]
    try:
        with log_path.open('w', encoding='utf-8') as log, tempfile.TemporaryDirectory(prefix='wled-models-') as temporary:
            def execute(command, timeout=900):
                result = subprocess.run(command, stdout=log, stderr=subprocess.STDOUT, timeout=timeout,
                                        env={**os.environ, "PYTHONIOENCODING": "utf-8", "PYTHONUTF8": "1"})
                log.flush()
                return result.returncode == 0

            def read_models():
                return read_partition(port, connection, fs, temporary, execute)

            firmware_written = False
            try:
                print(f'[{port}] Uploading with normal PlatformIO firmware arguments...', flush=True)
                if not execute(upload):
                    return False, f'Firmware upload failed. {log_tail(log_path)} See {log_path}'
                firmware_written = True
                print(f'[{port}] Checking model files over USB...', flush=True)
                image = read_models()
                if helper.verify_models(image, files, fs['config']):
                    return True, f'Firmware uploaded; all {len(files)} model images correct, no image upload needed. See {log_path}'
                print(f'[{port}] Missing/incorrect model files; uploading repaired images...', flush=True)
                repaired = helper.repair_models(image, files, fs['config'], clean_image)
                repair_path = Path(temporary) / 'models-repair.bin'
                repair_path.write_bytes(repaired)
                if not execute(connection + ['write-flash', '-z', hex(fs['offset']), str(repair_path)]):
                    return False, f'Model repair upload failed. {log_tail(log_path)} See {log_path}'
                if not helper.verify_models(read_models(), files, fs['config']):
                    return False, f'Model files still incorrect after upload. See {log_path}'
                return True, f'Firmware uploaded; all {len(files)} model images repaired and verified. See {log_path}'
            finally:
                if firmware_written:
                    try:
                        if not execute(connection + ['run'], timeout=30):
                            raise RuntimeError('Could not restart firmware after model verification; reset the board manually')
                    except (OSError, subprocess.TimeoutExpired):
                        raise RuntimeError('Could not restart firmware after model verification; reset the board manually')

    except (OSError, RuntimeError, ValueError, subprocess.TimeoutExpired) as error:
        return False, f'{type(error).__name__}: {error}. {log_tail(log_path)} See {log_path}'


def upload_devices(ports, plan, assets, logs, worker=upload_port):
    """Run one independent upload per selected USB port and report every result."""
    if not ports:
        raise ValueError('No matching USB serial devices found')
    logs.mkdir(parents=True, exist_ok=True)
    results = {}
    print('Parallel normal uploads + model-file verification: ' + ', '.join(ports), flush=True)
    with ThreadPoolExecutor(max_workers=len(ports)) as pool:
        pending = {pool.submit(worker, port, plan, assets, logs): port for port in ports}
        for future in as_completed(pending):
            port = pending[future]
            try:
                success, detail = future.result()
            except Exception as error:
                success, detail = False, f'{type(error).__name__}: {error}'
            results[port] = success
            print(f"[{'PASS' if success else 'FAIL'}] {port}: {detail}", flush=True)
    return 0 if all(results.values()) else 1


def main():
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, 'reconfigure'):
            stream.reconfigure(encoding='utf-8', errors='backslashreplace')
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--plan', type=Path)
    parser.add_argument('--ports', help='Optional comma-separated USB ports')
    parser.add_argument('--list', action='store_true', help='List selected ports without opening them')
    parser.add_argument('--dry-run', action='store_true', help='Validate and show normal upload commands without opening ports')
    args = parser.parse_args()
    from serial.tools.list_ports import comports
    try:
        ports = select_ports(comports(), args.ports)
        if args.list:
            print('Selected USB ports: ' + (', '.join(ports) or 'none'))
            return 0
        if args.plan is None:
            parser.error('Use pio run -t uploadall so the normal upload plan is generated')
        plan, assets = load_plan(args.plan)
        if args.dry_run:
            for port in ports:
                print(subprocess.list2cmdline([plan['uploader'], *[port if item == '@PORT@' else item for item in plan['arguments']]]))
            return 0
        logs = Path(__file__).resolve().parent.parent / 'build_output/flash-all' / datetime.now().strftime('%Y%m%d-%H%M%S-%f')
        return upload_devices(ports, plan, assets, logs)
    except (OSError, KeyError, ValueError) as error:
        parser.error(str(error))


if __name__ == '__main__':
    raise SystemExit(main())
